-- G22: independent question/answer QA against the final QA-passed passage.
create table public.question_qa_versions(id uuid primary key default gen_random_uuid(),version text unique not null,config jsonb not null,status text not null check(status in('draft','active','retired')),activated_at timestamptz,created_at timestamptz not null default now(),check((status='active')=(activated_at is not null)));
insert into public.question_qa_versions(version,config,status,activated_at) values('1.0.0','{"require_evidence_span":true,"require_unique_closed_answer":true,"external_knowledge_default":false,"tense_focus":["form","meaning","chronology","discourse_effect"]}','active',now());
create table public.generated_candidate_questions(id uuid primary key default gen_random_uuid(),candidate_id uuid not null references public.contract_generation_candidates(id) on delete restrict,question_key text not null,question_payload jsonb not null,declared_competency_id uuid references public.competency_nodes(id) on delete restrict,declared_demand text not null check(declared_demand in('literal','vocabulary_in_context','inference','analysis','tense')),tense_focus text check(tense_focus in('form','meaning','chronology','discourse_effect')),created_at timestamptz not null default now(),unique(candidate_id,question_key));
create table public.question_qa_results(id uuid primary key default gen_random_uuid(),question_id uuid not null references public.generated_candidate_questions(id) on delete restrict,passage_qa_result_id uuid not null references public.passage_qa_results(id) on delete restrict,qa_version_id uuid not null references public.question_qa_versions(id) on delete restrict,decision text not null check(decision in('pass','fail','human_review')),independent_answer text not null,answer_confidence numeric not null check(answer_confidence between 0 and 1),evidence_spans jsonb not null,defensible_answers jsonb not null,actual_competency_id uuid references public.competency_nodes(id) on delete set null,actual_demand text not null,distractor_analysis jsonb not null,tense_validation jsonb,failures jsonb not null,explanation jsonb not null,evaluator_provider text not null,evaluator_model text not null,created_at timestamptz not null default now(),unique(question_id,qa_version_id));
alter table public.question_qa_versions enable row level security;alter table public.generated_candidate_questions enable row level security;alter table public.question_qa_results enable row level security;create policy question_qa_version_read on public.question_qa_versions for select using(status='active' or public.is_platform_admin());create policy generated_questions_staff_read on public.generated_candidate_questions for select using(public.is_staff());create policy question_qa_staff_read on public.question_qa_results for select using(public.is_staff());grant select on public.question_qa_versions,public.generated_candidate_questions,public.question_qa_results to authenticated;
